{"code": "import math

def haversine(lat1, lon1, lat2, lon2):
    R = 6371.0  # Earth's mean radius in km
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dphi = math.radians(lat2 - lat1)
    dlmb = math.radians(lon2 - lon1)
    a = math.sin(dphi/2)**2 + math.cos(p1)*math.cos(p2)*math.sin(dlmb/2)**2
    return 2*R*math.asin(math.sqrt(a))

# Goa (Piso HQ, Caranzalem/Taleigao near Panaji)
goa_options = {
    "Panaji/Caranzalem": (15.4909, 73.8278),
    "Taleigao":          (15.4870, 73.8120),
}

# Lille / Decathlon HQ (Villeneuve-d'Ascq)
lille_options = {
    "Lille centre":          (50.6292, 3.0573),
    "Villeneuve-d'Ascq":     (50.6292, 3.1650),
    "Englos (Decathlon HQ)": (50.6086, 3.0206),
}

print("Great-circle distances (km):\n")
results = []
for gname,(gla,glo) in goa_options.items():
    for lname,(lla,llo) in lille_options.items():
        d = haversine(gla,glo,lla,llo)
        results.append(d)
        print(f"Goa[{gname}] -> Lille[{lname}]: {d:,.0f} km")

print(f"\nRange: {min(results):,.0f} - {max(results):,.0f} km")
print(f"Approximate average: {sum(results)/len(results):,.0f} km")"}

